    const b = el('button', 'sort_challenge__bin');
    b.type = 'button';
    b.setAttribute('data-sort_challenge_cat', c.id);
    b.appendChild(document.createTextNode(c.label));
    if (c.hint) b.appendChild(el('span', 'sort_challenge__binHint', c.hint));
    binsWrap.appendChild(b);
